dashboard.definition:
{
  "title": "Vue d'ensemble des comptes AD",
  "description": "Vue d'hygiène des comptes Active Directory construite sur les lookups de l'app Microsoft Windows Active Directory Objects (voir le README pour adapter les noms de lookups/macros) : actifs vs désactivés, mot de passe sans expiration, verrouillés, expirés, inactifs, privilégiés et configurations à risque. Les chiffres reflètent le dernier rafraîchissement des lookups, pas du LDAP en direct.",
  "inputs": {
    "input_ou": {
      "type": "input.text",
      "title": "Filtre OU (regex, ex. OU=Admins)",
      "options": {
        "token": "ou_f",
        "defaultValue": ".*"
      }
    }
  },
  "defaults": {},
  "visualizations": {
    "viz_1": {
      "type": "splunk.singlevalue",
      "title": "Comptes utilisateurs",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "title": "Actifs",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "title": "Désactivés",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "title": "Mot de passe sans expiration (actifs)",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "title": "Verrouillés",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "title": "Mot de passe non requis (actifs)",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_7": {
      "type": "splunk.singlevalue",
      "title": "Expirés mais toujours actifs",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_8": {
      "type": "splunk.singlevalue",
      "title": "Comptes actifs inactifs",
      "dataSources": {
        "primary": "ds_8"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
        "underLabel": "aucune connexion depuis plus de adx_stale_days jours"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_9": {
      "type": "splunk.singlevalue",
      "title": "Comptes privilégiés (actifs)",
      "dataSources": {
        "primary": "ds_9"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_10": {
      "type": "splunk.singlevalue",
      "title": "Âge du mot de passe krbtgt (jours)",
      "dataSources": {
        "primary": "ds_10"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 180
          },
          {
            "value": "#B0413E",
            "from": 180
          }
        ]
      }
    },
    "viz_11": {
      "type": "splunk.singlevalue",
      "title": "Mot de passe expiré (actifs)",
      "dataSources": {
        "primary": "ds_11"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
        "underLabel": "plus ancien que adx_max_pwd_age_days"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_12": {
      "type": "splunk.singlevalue",
      "title": "Mot de passe expirant sous 14 jours",
      "dataSources": {
        "primary": "ds_12"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_13": {
      "type": "splunk.singlevalue",
      "title": "Doit changer son mot de passe à la prochaine connexion",
      "dataSources": {
        "primary": "ds_13"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_14": {
      "type": "splunk.singlevalue",
      "title": "Comptes non conformes aux règles de mot de passe",
      "dataSources": {
        "primary": "ds_14"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_15": {
      "type": "splunk.singlevalue",
      "title": "Mots de passe privilégiés trop anciens",
      "dataSources": {
        "primary": "ds_15"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_16": {
      "type": "splunk.bar",
      "title": "Violations des règles de mot de passe (comptes actifs)",
      "dataSources": {
        "primary": "ds_16"
      },
      "options": {
        "legendDisplay": "off"
      },
      "description": "Basé sur les indicateurs UAC, l'âge du mot de passe et l'appartenance privilégiée. AD n'expose pas le contenu des mots de passe : les mots de passe faibles, compromis ou de dictionnaire nécessitent un audit hors ligne (ex. DSInternals Test-PasswordQuality) ou une protection des mots de passe Entra/AD."
    },
    "viz_17": {
      "type": "splunk.table",
      "title": "Comptes non conformes aux règles de mot de passe",
      "dataSources": {
        "primary": "ds_17"
      },
      "options": {
        "count": 10,
        "wrap": true,
        "columnFormat": {
          "Privilégié": {
            "rowBackgroundColors": "> table | seriesByName(\"Privilégié\") | matchValue(col0ColorConfig)"
          }
        }
      },
      "context": {
        "col0ColorConfig": [
          {
            "match": "OUI",
            "value": "#F8BE34"
          }
        ]
      }
    },
    "viz_18": {
      "type": "splunk.table",
      "title": "Mots de passe expirés ou expirant sous 14 jours",
      "dataSources": {
        "primary": "ds_18"
      },
      "options": {
        "count": 10,
        "wrap": true,
        "columnFormat": {
          "Statut": {
            "rowBackgroundColors": "> table | seriesByName(\"Statut\") | matchValue(col0ColorConfig)"
          }
        }
      },
      "description": "Valeur négative = jours depuis l'expiration du mot de passe (âge maximum du domaine = macro adx_max_pwd_age_days ; les politiques de mot de passe affinées ne sont pas prises en compte).",
      "context": {
        "col0ColorConfig": [
          {
            "match": "EXPIRÉ",
            "value": "#B0413E"
          },
          {
            "match": "EXPIRE BIENTÔT",
            "value": "#F8BE34"
          }
        ]
      }
    },
    "viz_19": {
      "type": "splunk.pie",
      "title": "Actifs vs désactivés",
      "dataSources": {
        "primary": "ds_19"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_20": {
      "type": "splunk.pie",
      "title": "Situation des mots de passe des comptes actifs",
      "dataSources": {
        "primary": "ds_20"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_21": {
      "type": "splunk.column",
      "title": "Âge des mots de passe des comptes actifs",
      "dataSources": {
        "primary": "ds_21"
      },
      "options": {
        "legendDisplay": "off"
      }
    },
    "viz_22": {
      "type": "splunk.column",
      "title": "Dernière connexion des comptes actifs",
      "dataSources": {
        "primary": "ds_22"
      },
      "options": {
        "legendDisplay": "off"
      }
    },
    "viz_23": {
      "type": "splunk.bar",
      "title": "Mot de passe sans expiration - par OU (top 15, actifs)",
      "dataSources": {
        "primary": "ds_23"
      },
      "options": {
        "legendDisplay": "off"
      }
    },
    "viz_24": {
      "type": "splunk.table",
      "title": "Mot de passe sans expiration - comptes actifs",
      "dataSources": {
        "primary": "ds_24"
      },
      "options": {
        "count": 12,
        "wrap": true,
        "columnFormat": {
          "Privilégié": {
            "rowBackgroundColors": "> table | seriesByName(\"Privilégié\") | matchValue(col0ColorConfig)"
          }
        }
      },
      "context": {
        "col0ColorConfig": [
          {
            "match": "OUI",
            "value": "#F8BE34"
          }
        ]
      }
    },
    "viz_25": {
      "type": "splunk.table",
      "title": "Configurations de comptes à risque (actifs)",
      "dataSources": {
        "primary": "ds_25"
      },
      "options": {
        "count": 12,
        "wrap": true
      }
    },
    "viz_26": {
      "type": "splunk.table",
      "title": "Comptes expirant dans les 30 prochains jours",
      "dataSources": {
        "primary": "ds_26"
      },
      "options": {
        "count": 12,
        "wrap": true
      }
    },
    "viz_27": {
      "type": "splunk.table",
      "title": "Comptes actifs dont la date d'expiration est dépassée",
      "dataSources": {
        "primary": "ds_27"
      },
      "options": {
        "count": 8,
        "wrap": true
      }
    },
    "viz_28": {
      "type": "splunk.table",
      "title": "Comptes désactivés appartenant encore à un groupe privilégié",
      "dataSources": {
        "primary": "ds_28"
      },
      "options": {
        "count": 8,
        "wrap": true
      }
    },
    "viz_29": {
      "type": "splunk.table",
      "title": "Comptes actifs inactifs (connexion la plus ancienne d'abord)",
      "dataSources": {
        "primary": "ds_29"
      },
      "options": {
        "count": 8,
        "wrap": true
      }
    },
    "viz_30": {
      "type": "splunk.line",
      "title": "Tendance quotidienne (nécessite la recherche enregistrée « AD - KPI Snapshot »)",
      "dataSources": {
        "primary": "ds_30"
      },
      "options": {
        "legendDisplay": "bottom"
      },
      "description": "L'historique est construit par la recherche enregistrée « AD - KPI Snapshot to Summary Index », désactivée par défaut. Activez-la pour suivre l'évolution de ces chiffres."
    },
    "viz_31": {
      "type": "splunk.bar",
      "title": "Ordinateurs par système d'exploitation (top 10)",
      "dataSources": {
        "primary": "ds_31"
      },
      "options": {
        "legendDisplay": "off"
      }
    },
    "viz_32": {
      "type": "splunk.singlevalue",
      "title": "Ordinateurs actifs inactifs",
      "dataSources": {
        "primary": "ds_32"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "Comptes utilisateurs",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Actifs",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Désactivés",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Mot de passe sans expiration (actifs)",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND pwd_never_expires=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Verrouillés",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_locked=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Mot de passe non requis (actifs)",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND pwd_not_required=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Expirés mais toujours actifs",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND is_expired=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Comptes actifs inactifs",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND days_since_logon>`adx_stale_days` | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "Comptes privilégiés (actifs)",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND is_privileged=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "Âge du mot de passe krbtgt (jours)",
      "options": {
        "query": "| `adx_users` | where sam=\"krbtgt\" | stats max(pwd_age_days) as age",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "Mot de passe expiré (actifs)",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND pwd_expired=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "Mot de passe expirant sous 14 jours",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND isnotnull(pwd_days_left) AND pwd_days_left>=0 AND pwd_days_left<=14 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_13": {
      "type": "ds.search",
      "name": "Doit changer son mot de passe à la prochaine connexion",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND must_change_pwd=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_14": {
      "type": "ds.search",
      "name": "Comptes non conformes aux règles de mot de passe",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | `adx_pwd_violations` | where isnotnull(violations) | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_15": {
      "type": "ds.search",
      "name": "Mots de passe privilégiés trop anciens",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND is_privileged=1 AND pwd_age_days>`adx_priv_max_pwd_age_days` | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_16": {
      "type": "ds.search",
      "name": "Violations des règles de mot de passe (comptes actifs)",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | `adx_pwd_violations` | mvexpand violations | stats count by violations | sort - count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_17": {
      "type": "ds.search",
      "name": "Comptes non conformes aux règles de mot de passe",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | `adx_pwd_violations` | where isnotnull(violations) | eval n=mvcount(violations), privileged=if(is_privileged=1,\"OUI\",\"non\"), last_logon=strftime(last_logon,\"%Y-%m-%d\") | sort - n, - pwd_age_days | table sam display_name violations pwd_age_days last_logon privileged ou | rename sam as \"Compte\", display_name as \"Nom affiché\", violations as \"Violations\", pwd_age_days as \"Âge du mot de passe (j)\", last_logon as \"Dernière connexion\", privileged as \"Privilégié\", ou as \"OU\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_18": {
      "type": "ds.search",
      "name": "Mots de passe expirés ou expirant sous 14 jours",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND isnotnull(pwd_days_left) AND pwd_days_left<=14 | eval status=if(pwd_days_left<0,\"EXPIRÉ\",\"EXPIRE BIENTÔT\"), days_overdue_or_left=pwd_days_left, last_logon=strftime(last_logon,\"%Y-%m-%d\") | sort pwd_days_left | table sam display_name status days_overdue_or_left pwd_age_days last_logon ou | rename sam as \"Compte\", display_name as \"Nom affiché\", status as \"Statut\", days_overdue_or_left as \"Jours (négatif = dépassé)\", pwd_age_days as \"Âge du mot de passe (j)\", last_logon as \"Dernière connexion\", ou as \"OU\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_19": {
      "type": "ds.search",
      "name": "Actifs vs désactivés",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | eval state=if(is_disabled=1,\"Désactivé\",\"Actif\") | stats count by state",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_20": {
      "type": "ds.search",
      "name": "Situation des mots de passe des comptes actifs",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 | eval posture=case(pwd_never_expires=1,\"N'expire jamais\", pwd_age_days>`adx_max_pwd_age_days`,\"Plus ancien que la politique\", isnull(pwd_age_days),\"Inconnu\", true(),\"Dans la politique\") | stats count by posture",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_21": {
      "type": "ds.search",
      "name": "Âge des mots de passe des comptes actifs",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND isnotnull(pwd_age_days) | eval b=case(pwd_age_days<=30,\"1) 0-30 d\", pwd_age_days<=90,\"2) 31-90 d\", pwd_age_days<=180,\"3) 91-180 d\", pwd_age_days<=365,\"4) 181-365 d\", true(),\"5) > 1 an\") | stats count by b | sort b",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_22": {
      "type": "ds.search",
      "name": "Dernière connexion des comptes actifs",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 | eval b=case(isnull(days_since_logon),\"6) Jamais / inconnu\", days_since_logon<=7,\"1) <= 7 d\", days_since_logon<=30,\"2) 8-30 d\", days_since_logon<=90,\"3) 31-90 d\", days_since_logon<=180,\"4) 91-180 d\", true(),\"5) > 180 d\") | stats count by b | sort b",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_23": {
      "type": "ds.search",
      "name": "Mot de passe sans expiration - par OU (top 15, actifs)",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND pwd_never_expires=1 | stats count by ou | sort - count | head 15",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_24": {
      "type": "ds.search",
      "name": "Mot de passe sans expiration - comptes actifs",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND pwd_never_expires=1 | eval privileged=if(is_privileged=1,\"OUI\",\"non\"), last_logon=strftime(last_logon,\"%Y-%m-%d\") | sort - is_privileged, - pwd_age_days | table sam display_name ou pwd_age_days last_logon privileged | rename sam as \"Compte\", display_name as \"Nom affiché\", ou as \"OU\", pwd_age_days as \"Âge du mot de passe (j)\", last_logon as \"Dernière connexion\", privileged as \"Privilégié\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_25": {
      "type": "ds.search",
      "name": "Configurations de comptes à risque (actifs)",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 | eval risk=mvappend(if(pwd_not_required=1,\"Mot de passe non requis (PASSWD_NOTREQD)\",null()), if(no_preauth=1,\"Sans pré-authentification (AS-REP roastable)\",null()), if(trusted_for_delegation=1,\"Délégation non contrainte\",null()), if(pwd_never_expires=1 AND is_privileged=1,\"Privilégié + mot de passe sans expiration\",null()), if(is_privileged=1 AND days_since_logon>`adx_stale_days`,\"Privilégié + inactif\",null())) | where isnotnull(risk) | table sam display_name risk ou pwd_age_days | rename sam as \"Compte\", display_name as \"Nom affiché\", risk as \"Risque\", ou as \"OU\", pwd_age_days as \"Âge du mot de passe (j)\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_26": {
      "type": "ds.search",
      "name": "Comptes expirant dans les 30 prochains jours",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND isnotnull(acct_expires) AND acct_expires>now() AND acct_expires<now()+30*86400 | eval days_left=round((acct_expires-now())/86400,0), expires=strftime(acct_expires,\"%Y-%m-%d\") | sort days_left | table sam display_name expires days_left ou | rename sam as \"Compte\", display_name as \"Nom affiché\", expires as \"Expire le\", days_left as \"Jours restants\", ou as \"OU\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_27": {
      "type": "ds.search",
      "name": "Comptes actifs dont la date d'expiration est dépassée",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND is_expired=1 | eval expired_on=strftime(acct_expires,\"%Y-%m-%d\") | table sam display_name expired_on ou | rename sam as \"Compte\", display_name as \"Nom affiché\", expired_on as \"Expiré le\", ou as \"OU\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_28": {
      "type": "ds.search",
      "name": "Comptes désactivés appartenant encore à un groupe privilégié",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=1 AND is_privileged=1 | table sam display_name ou priv_groups | rename sam as \"Compte\", display_name as \"Nom affiché\", ou as \"OU\", priv_groups as \"Groupes privilégiés\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_29": {
      "type": "ds.search",
      "name": "Comptes actifs inactifs (connexion la plus ancienne d'abord)",
      "options": {
        "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") | where is_disabled=0 AND days_since_logon>`adx_stale_days` | eval last_logon=strftime(last_logon,\"%Y-%m-%d\") | sort - days_since_logon | table sam display_name last_logon days_since_logon ou | rename sam as \"Compte\", display_name as \"Nom affiché\", last_logon as \"Dernière connexion\", days_since_logon as \"Jours sans connexion\", ou as \"OU\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_30": {
      "type": "ds.search",
      "name": "Tendance quotidienne (nécessite la recherche enregistrée « AD - KPI Snapshot »)",
      "options": {
        "query": "index=summary sourcetype=adx_kpi_snapshot | timechart span=1d max(never_expire_enabled) as \"Never expires (enabled)\", max(disabled) as \"Désactivé\", max(stale_enabled) as \"Stale enabled\", max(locked) as \"Locked\"",
        "queryParameters": {
          "earliest": "-90d@d",
          "latest": "now"
        }
      }
    },
    "ds_31": {
      "type": "ds.search",
      "name": "Ordinateurs par système d'exploitation (top 10)",
      "options": {
        "query": "| `adx_computers` | where is_disabled=0 | stats count by os | sort - count | head 10",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_32": {
      "type": "ds.search",
      "name": "Ordinateurs actifs inactifs",
      "options": {
        "query": "| `adx_computers` | where is_disabled=0 AND days_since_logon>`adx_stale_days` | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    }
  },
